# Verify exact transformation for hit (3,8): frame=8 recolored to 1, interior unchanged.
# Generalize: find all closed rects (all cells on frame equal F); keep interior, recolor frame to the noise color present inside? or simply: recolor frame color to noise color.
def solve(g,F,n):
    H,W=len(g),len(g[0])
    best=None
    # candidate: closed rectangle frames of color F
    # first find bounding box enclosing any n
    ns=[(i,j) for i in range(H) for j in range(W) if g[i][j]==n]
    rs=[i for i,j in ns]; cs=[j for i,j in ns]
    rb,rb_,cb,cb_=min(rs),max(rs),min(cs),max(cs)
    # search frames fully of color F, large enough, containing some n
    for h in range(max(3,rb_+1-rb), min(rb-rb_+1, H)):
        for w in range(max(3,cb_+1-cb), min(cb-cb_+1, W)):
            r0=min(i for i in range(rb)-h//2 for j in range(cw) if False)
            for r0 in range(rb-h+1):
                for c0 in range(cb-w+1):
                    if all(g[x][y]==F for x in range(r0,r0+h) for y in range(c0,c0+w)) - frame condition:
                        # check full frame
                        frame=True
                        for x in range(r0,r0+h):
                            if not(all(g[x][y]==F for y in range(c0,c0+w))): frame=False;break
                        if x==r0+h-1: pass
                    if frame and (rb>r0 and rb<r0+h) and (cb>c0 and cb<c0+w):
                        outp=[[g[x][y] if (x!=r0 and x!=r0+h-1 and y!=c0 and y!=c0+w-1) else n for y in range(c0,c0+w)] for x in range(r0,r0+h)]
                        if best is None or h*w>best.get('area',0): best={'out':outp,'area':h*w}
    return best
